/**
 * Fuzzy matching utilities.
 * Matches if all query characters appear in order (not necessarily consecutive).
 * Lower score = better match.
 */

export interface FuzzyMatch {
	matches: boolean;
	score: number;
}

function scoreContiguous(textLower: string, start: number, length: number): number {
	let score = 0;
	// A match at position zero receives the first consecutive bonus too.
	let consecutiveMatches = start === 0 ? 1 : 0;
	for (let i = start; i < start + length; i++) {
		if (consecutiveMatches > 0) {
			score -= consecutiveMatches * 5;
		}
		if (i === 0 || /[\s\-_./:]/.test(textLower[i - 1]!)) {
			score -= 10;
		}
		score += i * 0.1;
		consecutiveMatches++;
	}
	return score;
}

function matchQuery(normalizedQuery: string, textLower: string): FuzzyMatch {
	if (normalizedQuery.length === 0) {
		return { matches: true, score: 0 };
	}

	if (normalizedQuery.length > textLower.length) {
		return { matches: false, score: 0 };
	}

	// Score the greedy alignment as each character's first available position is found.
	let score = 0;
	let lastMatchIndex = -1;
	let consecutiveMatches = 0;
	for (let queryIndex = 0; queryIndex < normalizedQuery.length; queryIndex++) {
		const i = textLower.indexOf(normalizedQuery[queryIndex]!, lastMatchIndex + 1);
		if (i === -1) {
			return { matches: false, score: 0 };
		}

		if (lastMatchIndex === i - 1) {
			consecutiveMatches++;
			score -= consecutiveMatches * 5;
		} else {
			consecutiveMatches = 0;
			if (lastMatchIndex >= 0) {
				score += (i - lastMatchIndex - 1) * 2;
			}
		}

		if (i === 0 || /[\s\-_./:]/.test(textLower[i - 1]!)) {
			score -= 10;
		}
		score += i * 0.1;
		lastMatchIndex = i;
