		if (/^(?:[0-9a-f]{3}){1,4}$/i.test(hex)) {
			return hexToRgb(value);
		}
		return undefined;
	}

	const match = /^(rgb|rgba):(.+)$/i.exec(value);
	if (!match) {
		return undefined;
	}
	const channels = match[2].split("/");
	const expectedCount = match[1].toLowerCase() === "rgba" ? 4 : 3;
	if (channels.length !== expectedCount) {
		return undefined;
	}
	const decoded = channels.map(parseOscHexChannel);
	if (decoded.some((channel) => channel === undefined)) {
		return undefined;
	}
	const [r, g, b] = decoded;
	return r !== undefined && g !== undefined && b !== undefined ? { r, g, b } : undefined;
}

